/* DOOM CLONE — CSS retro FPS */
/* Variáveis e reset */
:root {
  --bg: #1a1a1a;
  --panel-bg: #1a1a1a;
  --border: #aa2222;
  --health: #33aa33;
  --armor: #3366cc;
  --ammo: #b08d57;
  --text: #cccccc;
  --hud-bar: #2a2a2a;
  --overlay-bg: rgba(0, 0, 0, 0.75);
  --crosshair: #33aa33;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: "Courier New", monospace;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
}

#game {
  display: block;
  width: 100%;
  height: 100%;
  cursor: none;
}

/* Scanline sutil */
#game::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.08),
    rgba(0, 0, 0, 0.08) 1px,
    transparent 1px,
    transparent 2px
  );
  pointer-events: none;
  z-index: 10;
}

/* HUD — painel inferior */
#hud {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 64px;
  background: var(--panel-bg);
  border-top: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 12px;
  z-index: 5;
}

/* Barras health + armor */
#bars {
  display: flex;
  gap: 12px;
}

.bar-wrap {
  width: 120px;
  height: 16px;
  background: var(--hud-bar);
  border: 1px solid #444;
  position: relative;
}

.bar-fill {
  height: 100%;
  width: 100%;
  border-radius: 2px;
  transition: width 0.2s;
}

.bar-fill.health { background: var(--health); }
.bar-fill.armor { background: var(--armor); }

.bar-label {
  position: absolute;
  top: -14px;
  left: 2px;
  font-size: 11px;
  font-weight: bold;
}

/* Ammo */
#ammo {
  font-size: 20px;
  font-weight: bold;
  color: var(--ammo);
  letter-spacing: 1px;
  white-space: nowrap;
  padding-left: 12px;
}

/* Weapon slots */
#weapons {
  display: flex;
  gap: 8px;
}

.wslot {
  width: 24px;
  height: 24px;
  border: 1px solid #666;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: bold;
}

.wslot.active {
  border-color: var(--border);
  background: #331111;
}

/* Score */
#score {
  font-size: 12px;
  color: #888;
  white-space: nowrap;
}

/* Crosshair */
#crosshair {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 24px;
  color: var(--crosshair);
  pointer-events: none;
  z-index: 5;
}

/* Overlays: MENU, PAUSED, DEAD, WIN */
.overlay {
  position: absolute;
  inset: 0;
  background: var(--overlay-bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 20;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s;
}

.overlay.visible {
  opacity: 1;
  pointer-events: auto;
}

.overlay h1 {
  font-size: 48px;
  color: var(--border);
  letter-spacing: 6px;
  margin-bottom: 20px;
  text-shadow: 0 0 10px var(--border);
}

.overlay p {
  font-size: 18px;
  color: var(--text);
  margin-bottom: 8px;
}

.overlay .hint {
  font-size: 14px;
  color: #888;
  margin-top: 30px;
}

/* Minimap */
#minimap {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 128px;
  height: 128px;
  border: 1px solid var(--border);
  background: #000;
  z-index: 5;
}

